/**
 * Shared MCP JSON-RPC stdio loop (shipped with thetowersdk; reused by monorepo tower-mcp).
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    argumentProblems, unreadKeys, runStdioMcp, isDirectRun
 * depends    —
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

/**
 * Protocol revisions this loop can speak, newest first.
 *
 * The surface used here -- initialize, ping, tools/list, tools/call -- has the same shape in all
 * of them, so the server answers in whichever one the client asked for. A client that names a
 * revision this list does not hold gets the newest one, which is what the specification asks of
 * a server; a client that names none gets the oldest, which is what this server always said.
 */
const PROTOCOL_VERSIONS = ['2025-06-18', '2025-03-26', '2024-11-05']

/**
 * How much of a description `tools/list` carries.
 *
 * It was 180 characters for everyone, to fit one client's catalog -- and 28 of 46 descriptions are
 * longer than that. What was cut was the instruction: `oracle_expand` lost "DO NOT expand an
 * acronym from memory", `oracle_traps` lost everything after the list of systems. The description
 * is the only contract an agent has, and the audits read the source, so nothing noticed.
 *
 * `TOWER_MCP_COMPACT=1` restores the short form for a client that needs it.
 */
const DESCRIPTION_LIMIT = process.env.TOWER_MCP_COMPACT === '1' ? 180 : 1024

const typeOf = value => (Array.isArray(value) ? 'array' : value === null ? 'null' : typeof value)

/**
 * Check arguments against the schema the tool advertised.
 *
 * `inputSchema` was published and never enforced, so a missing required array reached the tool
 * body and came back as "Cannot read properties of undefined (reading 'map')" -- an answer about
 * the server's internals to a question about the caller's arguments.
 *
 * Deliberately small: required keys, primitive types, and arrays of one primitive. Enums are left
 * to the tool: a wrong name there is answered with the nearest real ones, which is more use than
 * "must be one of" followed by the list the caller already had. Unknown keys are refused
 * separately, by `unreadKeys` below.
 */
export function argumentProblems(schema, args) {
  const problems = []
  if (!schema || typeof schema !== 'object') return problems
  const properties = schema.properties ?? {}

  for (const key of schema.required ?? []) {
    if (!Object.prototype.hasOwnProperty.call(args, key) || args[key] === undefined || args[key] === null) {
      problems.push(`\`${key}\` is required`)
    }
  }

  for (const [key, spec] of Object.entries(properties)) {
    if (!Object.prototype.hasOwnProperty.call(args, key)) continue
    const value = args[key]
    if (value === undefined || value === null) continue
    const actual = typeOf(value)
    if (typeof spec?.type === 'string' && spec.type !== actual
      && !(spec.type === 'integer' && actual === 'number')) {
      problems.push(`\`${key}\` must be ${spec.type === 'array' || spec.type === 'object' ? 'an' : 'a'} ${spec.type}, got ${actual}`)
      continue
    }
    if (actual === 'array' && typeof spec?.items?.type === 'string') {
      const bad = value.findIndex(entry => typeOf(entry) !== spec.items.type)
      if (bad !== -1) problems.push(`\`${key}[${bad}]\` must be a ${spec.items.type}, got ${typeOf(value[bad])}`)
    }
  }
  return problems
}

/** Edit distance, capped: only "is this a slip of that" is ever asked of it. */
function editDistance(a, b) {
  if (Math.abs(a.length - b.length) > 2) return 3
  let row = Array.from({ length: b.length + 1 }, (_, i) => i)
  for (let i = 1; i <= a.length; i += 1) {
    const next = [i]
    for (let j = 1; j <= b.length; j += 1) {
      next[j] = Math.min(row[j] + 1, next[j - 1] + 1, row[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1))
    }
    row = next
  }
  return row[b.length]
}

/**
 * Arguments the tool has no parameter for.
 *
 * These used to pass, on the reasoning that one extra field is not a mistake worth refusing. It
 * is when the extra field was the point of the call. Six tools name the save `path` and three name
 * it `savePath`, so `battle_history({ savePath })` dropped the key, found a different save on the
 * machine and answered about that one. `find_rows({ filter })` returned every row to a caller who
 * had asked for some. A dropped argument produces an answer to a question nobody asked, and the
 * answer looks right.
 *
 * A tool that refuses its own unread keys with a more specific message sets `checksOwnArguments`.
 */
export function unreadKeys(schema, args) {
  const known = Object.keys(schema?.properties ?? {})
  const unread = Object.keys(args).filter(key => !known.includes(key))
  if (unread.length === 0) return null
  const lower = known.map(key => [key, key.toLowerCase()])
  const near = [...new Set(unread.flatMap((key) => {
    const asked = key.toLowerCase()
    return lower
      .filter(([, name]) => name.includes(asked) || asked.includes(name) || editDistance(asked, name) <= 2)
      .map(([name]) => name)
  }))]
  return { known, unread, near }
}

/**
 * Leave out what the caller sent as `null`.
 *
 * JSON has no `undefined`, so a client with nothing to say about an optional parameter sends
 * `null`. The type check already let that through; the tool then received a real `null`, and
 * `coin_bonus({ tier: null })` answered "Tier null has no coin bonus".
 */
function withoutNulls(args) {
  return Object.fromEntries(Object.entries(args).filter(([, value]) => value !== null && value !== undefined))
}

/**
 * Every number in a result that JSON cannot carry.
 *
 * `JSON.stringify(NaN)` is `null`, and so is `Infinity`. A formula handed arguments it cannot use
 * returns NaN, the response says `null`, and that is indistinguishable from a formula that
 * legitimately returns nothing. The value is left alone; the paths are reported beside it.
 */
function nonFinitePaths(value, at = 'result', found = [], depth = 0) {
  if (found.length >= 20 || depth > 12) return found
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) found.push(`${at} = ${Number.isNaN(value) ? 'NaN' : String(value)}`)
    return found
  }
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length && found.length < 20; i += 1) nonFinitePaths(value[i], `${at}[${i}]`, found, depth + 1)
    return found
  }
  if (value && typeof value === 'object') {
    for (const [key, entry] of Object.entries(value)) {
      if (found.length >= 20) break
      nonFinitePaths(entry, `${at}.${key}`, found, depth + 1)
    }
  }
  return found
}

/**
 * Whether a tool's answer is a failure.
 *
 * Tools report a wrong name or a missing file as `{ error }` so the message can carry suggestions,
 * and the loop sent those as ordinary successes. A client that branches on `isError` -- which is
 * what the flag is for -- saw every mistyped export as a call that worked.
 */
function reportsFailure(result) {
  if (!result || typeof result !== 'object' || Array.isArray(result)) return false
  const has = key => Object.prototype.hasOwnProperty.call(result, key)
  return (has('error') && Boolean(result.error)) || (has('ok') && result.ok === false)
}

export function runStdioMcp({ name, version, instructions, tools }) {
  const send = msg => process.stdout.write(`${JSON.stringify(msg)}\n`)
  const own = (record, key) => Object.prototype.hasOwnProperty.call(record, key) ? record[key] : undefined
  const fail = (id, code, message) => send({ jsonrpc: '2.0', id, error: { code, message } })

  const handlers = {
    initialize: ({ protocolVersion } = {}) => ({
      protocolVersion: protocolVersion === undefined
        ? PROTOCOL_VERSIONS.at(-1)
        : PROTOCOL_VERSIONS.includes(protocolVersion) ? protocolVersion : PROTOCOL_VERSIONS[0],
      capabilities: { tools: {} },
      serverInfo: { name, version },
      instructions,
    }),
    /* A liveness check. Unanswered, a client that pings on a timer concludes the server died. */
    ping: () => ({}),
    'tools/list': () => ({
      tools: Object.entries(tools).map(([toolName, t]) => {
        const desc = String(t.description ?? '')
        return {
          name: toolName,
          description: desc.length > DESCRIPTION_LIMIT ? `${desc.slice(0, DESCRIPTION_LIMIT - 3)}...` : desc,
          inputSchema: t.inputSchema ?? { type: 'object', properties: {} },
          ...(t.annotations ? { annotations: t.annotations } : {}),
        }
      }),
    }),
    'tools/call': async ({ name: toolName, arguments: args }) => {
      const tool = own(tools, toolName)
      if (!tool) {
        return { isError: true, content: [{ type: 'text', text: `unknown tool: ${toolName}` }] }
      }
      const given = args ?? {}
      if (typeof given !== 'object' || Array.isArray(given)) {
        return { isError: true, content: [{ type: 'text', text: `${toolName}: arguments must be an object` }] }
      }
      const problems = argumentProblems(tool.inputSchema, given)
      if (problems.length > 0) {
        return {
          isError: true,
          content: [{
            type: 'text',
            text: JSON.stringify({
              error: `${toolName}: invalid arguments — ${problems.join('; ')}`,
              problems,
              parameters: Object.fromEntries(
                Object.entries(tool.inputSchema?.properties ?? {}).map(([key, spec]) => [
                  key,
                  `${spec?.type ?? 'any'}${(tool.inputSchema?.required ?? []).includes(key) ? ' (required)' : ''}`,
                ]),
              ),
            }),
          }],
        }
      }
      // A tool that declares no parameters at all has published nothing to hold a call against.
      const unread = tool.checksOwnArguments || !tool.inputSchema?.properties
        ? null
        : unreadKeys(tool.inputSchema, given)
      if (unread) {
        return {
          isError: true,
          content: [{
            type: 'text',
            text: JSON.stringify({
              error: `${toolName} ${unread.known.length > 0 ? `takes ${unread.known.join(', ')}` : 'takes no arguments'}. `
                + `It does not read ${unread.unread.map(key => `"${key}"`).join(', ')}, so nothing was run.`,
              ...(unread.near.length > 0 ? { didYouMean: unread.near } : {}),
            }),
          }],
        }
      }
      try {
        const result = await tool.run(withoutNulls(given))
        const content = [{ type: 'text', text: JSON.stringify(result) ?? 'null' }]
        const lost = nonFinitePaths(result)
        if (lost.length > 0) {
          content.push({
            type: 'text',
            text: `warning: these numbers are not representable in JSON and appear above as null: ${lost.join('; ')}`,
          })
        }
        return reportsFailure(result) ? { isError: true, content } : { content }
      } catch (error) {
        return {
          isError: true,
          content: [{ type: 'text', text: `${toolName} failed: ${error instanceof Error ? error.message : String(error)}` }],
        }
      }
    },
  }

  let buffer = ''
  // Node's decoder retains incomplete UTF-8 sequences between pipe chunks.
  process.stdin.setEncoding('utf8')
  process.stdin.on('data', chunk => {
    buffer += chunk
    let newline
    while ((newline = buffer.indexOf('\n')) !== -1) {
      const line = buffer.slice(0, newline).trim()
      buffer = buffer.slice(newline + 1)
      if (!line) continue

      let request
      try {
        request = JSON.parse(line)
      } catch {
        fail(null, -32700, 'Parse error')
        continue
      }

      if (!request || typeof request !== 'object' || Array.isArray(request)
        || request.jsonrpc !== '2.0' || typeof request.method !== 'string'
        || (request.id !== undefined && request.id !== null && typeof request.id !== 'string' && typeof request.id !== 'number')) {
        fail(null, -32600, 'Invalid Request')
        continue
      }
      const hasId = Object.prototype.hasOwnProperty.call(request, 'id')
      const handler = own(handlers, request.method)
      if (!handler) {
        if (hasId) {
          send({
            jsonrpc: '2.0',
            id: request.id,
            error: { code: -32601, message: `unknown method: ${request.method}` },
          })
        }
        continue
      }
      if (request.params !== undefined && (!request.params || typeof request.params !== 'object' || Array.isArray(request.params))) {
        if (hasId) fail(request.id, -32602, 'Invalid params')
        continue
      }
      Promise.resolve()
        .then(() => handler(request.params ?? {}))
        .then(result => { if (hasId) send({ jsonrpc: '2.0', id: request.id, result }) })
        .catch(error => { if (hasId) fail(request.id, -32603, error instanceof Error ? error.message : String(error)) })
    }
  })
}

export function isDirectRun(importMetaUrl) {
  const entry = process.argv[1]
  if (!entry) return false
  try {
    return normalizePath(realPathOf(entry)) === normalizePath(realPathOf(fileURLToPath(importMetaUrl)))
  } catch {
    return false
  }
}

/**
 * The path with its symlinks followed.
 *
 * `process.argv[1]` is the path as it was typed, and `import.meta.url` is the file Node actually
 * loaded. Through `node_modules/.bin` -- which is how `npx thetowersdk-mcp` runs -- or a pnpm
 * install, those differ, and comparing them unresolved made the server conclude it had been
 * imported and exit without a word.
 */
function realPathOf(file) {
  const resolved = path.resolve(file)
  try {
    return fs.realpathSync(resolved)
  } catch {
    return resolved
  }
}

function normalizePath(p) {
  return String(p).replace(/\\/g, '/').toLowerCase()
}
